def load_concepts(domain_ttl):
    g = rdflib.Graph(); g.parse(domain_ttl, format='turtle')
    all_classes = sorted(str(c).split('#')[-1] for c in g.subjects(RDF.type, OWL.Class) if isinstance(c, rdflib.URIRef))
    # Filter to concepts with genuine, researched >=3-sentence prose (DEFS below) -- rather than a blind
    # alphabetical slice that could include concepts (e.g. SemanticTechnologyArea, Primitives) never
    # actually written up, which would either crash or force fabricated filler content (neither acceptable).
    covered = [c for c in all_classes if c in DEFS]
    return covered

